scenario.en:
:root {
  --gray-900: #111827;            /* primitive */
  --color-surface: #ffffff;       /* semantic */
  --color-on-surface: var(--gray-900);
}
[data-theme="dark"] {
  --color-surface: #0b0f1a;
  --color-on-surface: #e5e7eb;
}

.card { background: var(--color-surface); color: var(--color-on-surface); }
.legacy-badge { background: var(--color-surface); color: var(--gray-900); }

